-- ---------------------------------------------------------------------------
-- Phase 6 — Journal content (PROJECT_PLAN.md)
--
-- Replaces the Alam blog posts and categories with the /ci3/ journal
-- articles, and sets the Journal page (Web Pages 8) hero, sections and meta.
-- Requires docs/sql/phase-6-journal.sql (blogs.blog_service_id).
--
-- The image file names are uploads (not in the repository); on another
-- environment, upload the images through the admin instead.
-- ---------------------------------------------------------------------------

SET NAMES utf8mb4;

DELETE FROM `blog_assigned_cat`;
DELETE FROM `blogs`;
DELETE FROM `blog_categories` WHERE `cat_id` > 1;



UPDATE `pages` SET
    `banner_title` = 'Journal',
    `banner_heading` = 'Notes from the studio',
    `banner_text` = 'Practical things we end up explaining at the table — how to make gel last, what shape will suit you, and how to plan for a big day.',
    `banner_background` = '',
    `meta_description` = 'Nail care, manicure and beauty notes from Blossom Ewa Mazur in Gorlice — making gel last, choosing a nail shape and getting ready for an event.'
WHERE `page_id` = 8;

DELETE FROM `web_page_sections` WHERE `page_id` = 8 AND `section_key` NOT IN ('articles', 'cta');

